mapper.select:
select
  u.user_id,
  u.last_name ,
  u.first_name ,
  u.last_name_kana,
  u.first_name_kana,
  u.email ,
  r.role_id,
  r.name as roleName,
  u.is_active 
from users u 
join role r
    on u.role_id = r.role_id


    and u.role_id = #{roleId}


    and u.is_active = #{status}



    and ( 
      normalization(lower(u.last_name)) ~ #{keywordRegex}
      or normalization(lower(u.first_name)) ~#{keywordRegex}
      or normalization(lower(u.last_name_kana)) ~#{keywordRegex}
      or normalization(lower(u.first_name_kana)) ~#{keywordRegex}
      or normalization(lower(concat(u.last_name_kana, u.first_name_kana))) ~#{keywordRegex}
      or normalization(lower(concat(u.last_name, u.first_name))) ~#{keywordRegex}
    )


order by

    concat(u.last_name_kana, u.first_name_kana)
    u.email
    r.name
    u.is_active


    asc
    desc

limit #{size} offset #{offset}

select count(*)
from users u 


    and u.role_id = #{roleId}


    and u.is_active = #{status}



    and ( 
      normalization(lower(u.last_name)) ~ #{keywordRegex}
      or normalization(lower(u.first_name)) ~#{keywordRegex}
      or normalization(lower(u.last_name_kana)) ~#{keywordRegex}
      or normalization(lower(u.first_name_kana)) ~#{keywordRegex}
      or normalization(lower(concat(u.last_name_kana, u.first_name_kana))) ~#{keywordRegex}
      or normalization(lower(concat(u.last_name, u.first_name))) ~#{keywordRegex}
    )
